  // A line in the {{proof}} block's runs list, newest first, with a child
  // per case, so whoever opens the page sees what passed on which build.
  private async writeRunLog(source: Kit, records: Record<string, CaseRecord>, ran: string[], stopped: boolean, leftOut: string[] = [], whys: Record<string, string> = {}): Promise<void> {
    const tree = await readTree(this.rootUid);
    if (!tree) return;
    let runs = (tree.children ?? []).find((child) => child.string.trim().toLowerCase() === "runs");
    if (!runs?.uid) {
      const uid = roam().util.generateUID();
      await roam().data.block.create({
        location: { "parent-uid": this.rootUid, order: "last" },
        block: { string: "runs", uid, open: false },
      });
      runs = { uid, string: "runs" };
    }
    const count = (verdict: Verdict): number => source.cases.filter((item) => records[item.id]?.verdict === verdict).length;
    const passed = count("pass");
    const failed = count("fail");
    const skipped = count("skip");
    // A case the tester left out has no record; the rest that has none didn't run.
    const left = source.cases.filter((item) => leftOut.includes(item.id) && !records[item.id]).length;
    const notRun = source.cases.length - passed - failed - skipped - left;
    const build = this.env.build;
    const summary = [
      `${passed === source.cases.length ? "✓" : "✗"} ${passed}/${source.cases.length} passed`,
      failed ? `${failed} failed` : null,
      skipped ? `${skipped} couldn't be tested` : null,
      notRun ? `${notRun} not run` : null,
      left ? `${left} left out` : null,
      stopped ? "stopped" : null,
      this.scope === "failed" ? "re-ran the cases that didn't pass" : this.scope === "resume" ? "resumed" : null,
      build ? `build ${build.branch}${build.commit ? ` @ ${build.commit.slice(0, 7)}` : ""}` : "no build loaded",
      this.runInfo ? runWords(this.runInfo.pause, this.state?.speed ?? 1) : "",
      this.runInfo ? `took ${duration((this.runInfo.endedAt ?? Date.now()) - this.runInfo.startedAt).replace(/^about /, "")}` : "",
      stamp(new Date()),
      this.runInfo?.terminal ? "from the terminal" : "",
      await userName(),
    ]
      .filter(Boolean)
      .join(" · ");
    const fresh = new Set(ran);
    await createTree(
      runs.uid as string,
      [
        {
          string: summary,
          open: false,
          children: source.cases.map((item) => ({
            string: logLine(item.title, records[item.id] ?? null, Boolean(records[item.id]) && !fresh.has(item.id), leftOut.includes(item.id) ? { why: whys[item.id] ?? null } : undefined),
          })),
        },
      ],
      0,
    );
  }

  status(): Record<string, unknown> {
    const view = this.view();
    return {
      rootUid: this.rootUid,
      error: this.error,
      kit: this.kit?.kit.name ?? null,
      running: this.running,
      state: view.machine,
      checklist: view.checklist,
      warnings: this.warnings(),
    };
  }
}
